-- The Ashen Banner hosts the Quartermaster player window (Shop, Donate, Needs, My Week, officers' Manage) so guild
-- members only need this one addon. The files next to this one are copies of AshenKeeper's shared player-side
-- files (generated by scripts\Build-BannerQuartermaster.ps1 - edit them in AshenKeeper, never here) plus QM_Main.lua.
-- Grizzwick (the Keeper) keeps running AshenKeeper for the Keeper side.
--
-- Only one copy may run. AshenKeeper is an OptionalDep, so when it is installed it always loads first and defines
-- AshenKeeper: then every Quartermaster file in the Banner stands down (they all start with
-- "if ASHEN_QM_STANDDOWN then return end"): no second /qm, no second message handlers, no second set of
-- SavedVariables writes. The only thing the Banner still does then is copy AshenKeeper's player-side data into its
-- own SavedVariables at logout (LeafVE_QM_Migrate), so removing AshenKeeper later loses nothing.
-- Lua 5.0 / WoW 1.12: no '#', no '%'.

-- Player-side data from AshenKeeperDB / AshenKeeperCache into LeafVE_QuartermasterDB / ...Cache. Additive: what the
-- Banner already has is kept. The AE signature itself lives in LeafVE_DB.aeSig (the Banner's own data), so it needs
-- no copy; aeSigned (which characters were ever signed, used to spot a removed signature) is merged.
function LeafVE_QM_Migrate()
  if type(AshenKeeperDB) ~= "table" then return false end
  if type(LeafVE_QuartermasterDB) ~= "table" then LeafVE_QuartermasterDB = {} end
  if type(LeafVE_QuartermasterCache) ~= "table" then LeafVE_QuartermasterCache = {} end
  local to, from = LeafVE_QuartermasterDB, AshenKeeperDB
  to.config = to.config or {}
  local fc = from.config or {}
  if type(fc.keeperName) == "string" and fc.keeperName ~= "" then to.config.keeperName = fc.keeperName end
  if fc.transport then to.config.transport = fc.transport end
  if fc.dialogue ~= nil then to.config.dialogue = fc.dialogue end
  if fc.debug ~= nil then to.config.debug = fc.debug end
  local k, v
  -- leaderboard credits already booked (CREDIT x): never book one twice
  if type(from.credited) == "table" then
    to.credited = to.credited or {}
    for k, v in pairs(from.credited) do if to.credited[k] == nil then to.credited[k] = v end end
  end
  if type(from.aeSigned) == "table" then
    to.aeSigned = to.aeSigned or {}
    for k, v in pairs(from.aeSigned) do
      if type(v) == "number" and (to.aeSigned[k] == nil or v > to.aeSigned[k]) then to.aeSigned[k] = v end
    end
  end
  if type(from.ui) == "table" then
    to.ui = to.ui or {}
    for k, v in pairs(from.ui) do if to.ui[k] == nil then to.ui[k] = v end end
  end
  if type(AshenKeeperCache) == "table" and AshenKeeperCache.keeperName and not LeafVE_QuartermasterCache.keeperName then
    LeafVE_QuartermasterCache.keeperName = AshenKeeperCache.keeperName
  end
  to.migratedFromAK = time and time() or 0
  return true
end

if AshenKeeper then
  ASHEN_QM_STANDDOWN = true
  if CreateFrame then
    local f = CreateFrame("Frame", "LeafVE_QuartermasterMigrateFrame")
    f:RegisterEvent("PLAYER_LOGOUT")
    f:SetScript("OnEvent", function() pcall(LeafVE_QM_Migrate) end)
  end
  return
end

ASHEN_QM_STANDDOWN = nil
AshenKeeper = { host = "Banner" }
AshenKeeper.SV = {
  get = function() return LeafVE_QuartermasterDB, LeafVE_QuartermasterCache end,
  set = function(db, cache) LeafVE_QuartermasterDB = db LeafVE_QuartermasterCache = cache end,
}
-- The Banner's own version (Core.lua), sent as hb so the Keeper knows which addon to tell the player to update.
function AshenKeeper.HostVersion()
  return (LeafVE and LeafVE.version) or (LATEST_VERSION) or "?"
end
